INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT156-S4-Q24$batch02$, 156, 4, 24, $batch02$Parallel Flaw$batch02$, $batch02$A movie studio’s script readers discard all proposed scripts that are not submitted by agents, and they discard all scripts that are incorrectly formatted. So a script that is submitted by an agent and formatted correctly will not be discarded by the studio’s script readers.$batch02$, $batch02$Which one of the following exhibits a flawed pattern of reasoning that most closely parallels that in the argument above?$batch02$, $batch02$C$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$To be accepted, entries in the essay contest must be postmarked by the deadline and accompanied by a completed entry form. March 21 was the deadline. Thus, an entry that is accompanied by a completed entry form but postmarked March 22 will not be accepted.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$If your kitchen is well organized and you are a good cook, the meals you prepare will be delicious. The dinner Jon prepared last week was not at all tasty, so his kitchen must not be well organized.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$If Bob starts exercising daily, he will improve his fitness level. His fitness level will also improve if he quits smoking. So if he refuses to exercise and continues to smoke, his fitness level is not going to improve.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$The police are allowed to ticket any parked car that does not have a parking permit. They are also allowed to ticket any parked car whose parking permit has expired. Thus, the police are going to ticket Ruta’s car, for her parking permit has expired.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$Most dogs that have attended obedience classes respond correctly to basic commands, but only some are able to perform advanced tricks. Thus, any dog that has attended obedience classes and performs advanced tricks will be able to respond correctly to basic commands.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Agent-submitted, correctly formatted scripts will not be discarded.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Not from an agent → discarded. Incorrectly formatted → discarded.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Two separate triggers each lead to the same result. The argument negates both triggers and concludes the result will not happen. That is the illegal negation, twice. Readers could still discard a script for being too long or simply bad. Avoiding the two named reasons does not rule out every other reason.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Find two sufficient conditions for one outcome, both negated, with the outcome denied.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Postmark and entry form are *requirements* (necessary conditions). Missing one means no acceptance. That reasoning is valid, so it cannot match a flawed argument.$batch02$), ($batch02$B$batch02$, $batch02$One combined rule (organized + good cook → delicious), then a failed result, then blame placed on one specific part. The contrapositive only gives "not organized *or* not a good cook." That is a different error from negating two separate triggers.$batch02$), ($batch02$C$batch02$, $batch02$Exercise → fitness improves. Quit smoking → fitness improves. Bob does neither, so his fitness will not improve. Same structure: two separate sufficient conditions, both absent, outcome denied. Bob could improve his fitness by eating better or sleeping more.$batch02$), ($batch02$D$batch02$, $batch02$The rules say the police are *allowed* to ticket. The conclusion says they *will*. The flaw is treating permission as certainty, not negating two conditions.$batch02$), ($batch02$E$batch02$, $batch02$This mixes "most" and "some" statements. The structure is quantifier-based and does not deny an outcome from two absent triggers.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT156-S4-Q24$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
